-- =====================================================================
-- main.sql - Script autocontenido para cargar en una BD vacia
-- Incluye: extensiones (PostGIS, pgRouting), capas de infraestructura,
-- comunas, sismo Mw 8.8 (USGS), topologia (pgr_createTopology),
-- nodos clave y calculo de probabilidades de falla (Youngs 1997 + ALA 2001).
-- =====================================================================
CREATE EXTENSION IF NOT EXISTS postgis;
CREATE EXTENSION IF NOT EXISTS pgrouting;

-- Carga de capas de Respuesta_T5610 (WGS84, EPSG:4326). Generado desde los .shp/.dbf originales.
-- Uso: psql -U postgres -d resiliencia -f cargar_capas.sql
CREATE EXTENSION IF NOT EXISTS postgis;
BEGIN;
DROP TABLE IF EXISTS public.fibra;
CREATE TABLE public.fibra (gid serial PRIMARY KEY, id text, geom geometry(MultiLineString,4326));
CREATE INDEX fibra_geom_gix ON public.fibra USING GIST (geom);
DROP TABLE IF EXISTS public.postacion;
CREATE TABLE public.postacion (gid serial PRIMARY KEY, id text, geom geometry(MultiLineString,4326));
CREATE INDEX postacion_geom_gix ON public.postacion USING GIST (geom);
DROP TABLE IF EXISTS public.caminos_sin_postacion;
CREATE TABLE public.caminos_sin_postacion (gid serial PRIMARY KEY, id text, geom geometry(MultiLineString,4326));
CREATE INDEX caminos_sin_postacion_geom_gix ON public.caminos_sin_postacion USING GIST (geom);
DROP TABLE IF EXISTS public.ferry;
CREATE TABLE public.ferry (gid serial PRIMARY KEY, id text, geom geometry(MultiLineString,4326));
CREATE INDEX ferry_geom_gix ON public.ferry USING GIST (geom);
COMMIT;
SELECT 'fibra' t,count(*) FROM public.fibra UNION ALL SELECT 'postacion',count(*) FROM public.postacion UNION ALL SELECT 'caminos_sin_postacion',count(*) FROM public.caminos_sin_postacion UNION ALL SELECT 'ferry',count(*) FROM public.ferry;


-- Comunas (346) reproyectadas de Web Mercator (EPSG:3857) a WGS84 (EPSG:4326) y simplificadas (~50 m). Generado desde comunas_final.zip
SET client_encoding TO 'UTF8';
CREATE EXTENSION IF NOT EXISTS postgis;
BEGIN;
DROP TABLE IF EXISTS public.comunas;
CREATE TABLE public.comunas (gid serial PRIMARY KEY, cod_comuna int, comuna text, provincia text, region text, codregion int, geom geometry(MultiPolygon,4326));
CREATE INDEX comunas_geom_gix ON public.comunas USING GIST (geom);
COMMIT;
SELECT count(*) AS comunas, count(DISTINCT cod_comuna) AS codigos_distintos, sum(CASE WHEN ST_IsValid(geom) THEN 0 ELSE 1 END) AS invalidas FROM public.comunas;


-- Sismo del Maule 2010 (USGS official20100227063411530_30)
DROP TABLE IF EXISTS sismo;
CREATE TABLE sismo (
  titulo text,
  mag double precision,
  geom geometry(Point, 4326),
  prof_km double precision
);
  'M 8.8 - 2010 Maule, Chile Earthquake',
  8.8,
  ST_SetSRID(ST_MakePoint(-72.898, -36.122), 4326),
  22.9
);

-- Paso 3: unir las 4 capas en una sola red, nodar y crear la topologia (pgRouting).
-- La columna tipo permite calcular el escenario A (solo fibra) o B (todas las capas).
-- NOTA: pgr_createTopology esta marcada como obsoleta desde pgRouting 3.8 (sigue funcionando).
CREATE EXTENSION IF NOT EXISTS pgrouting;
DROP TABLE IF EXISTS red_edges_vertices_pgr;
DROP TABLE IF EXISTS red_edges;
DROP TABLE IF EXISTS red_lineas;

CREATE TABLE red_lineas AS
SELECT 'fibra'::text AS tipo, (ST_Dump(ST_Force2D(geom))).geom AS geom FROM fibra
UNION ALL SELECT 'poste',  (ST_Dump(ST_Force2D(geom))).geom FROM postacion
UNION ALL SELECT 'camino', (ST_Dump(ST_Force2D(geom))).geom FROM caminos_sin_postacion
UNION ALL SELECT 'ferry',  (ST_Dump(ST_Force2D(geom))).geom FROM ferry;
CREATE INDEX red_lineas_gix ON red_lineas USING GIST (geom);

-- Nodado (ST_Node) y asignacion de tipo; prioridad fibra > poste > camino > ferry donde se superponen
CREATE TABLE red_edges AS
WITH noded AS (SELECT (ST_Dump(ST_Node(ST_Collect(geom)))).geom AS geom FROM red_lineas)
SELECT row_number() OVER () AS id, n.geom::geometry(LineString,4326) AS geom,
  COALESCE((SELECT r.tipo FROM red_lineas r
            WHERE ST_DWithin(r.geom, ST_LineInterpolatePoint(n.geom,0.5), 0.000001)
            ORDER BY CASE r.tipo WHEN 'fibra' THEN 1 WHEN 'poste' THEN 2
                                 WHEN 'camino' THEN 3 ELSE 4 END LIMIT 1),'desconocido') AS tipo
FROM noded n;

ALTER TABLE red_edges
  ADD source int,
  ADD target int,
  ADD length_m double precision,
  ADD es_sintetico boolean DEFAULT false,
  ADD prob_falla double precision DEFAULT 0;

UPDATE red_edges
SET length_m = ST_Length(geom::geography),
    es_sintetico = (tipo <> 'fibra');

SELECT pgr_createTopology('red_edges', 0.00001, 'geom', 'id');

-- Verificacion de conectividad base (componentes conexas y vertices)
SELECT count(*) AS total_vertices FROM red_edges_vertices_pgr;
SELECT count(DISTINCT component) AS componentes_red_b
FROM pgr_connectedComponents(
  'SELECT id, source, target, 1.0 AS cost, 1.0 AS reverse_cost FROM red_edges'
);
SELECT count(DISTINCT component) AS componentes_red_a_fibra
FROM pgr_connectedComponents(
  'SELECT id, source, target, 1.0 AS cost, 1.0 AS reverse_cost FROM red_edges WHERE tipo = ''fibra'''
);


-- Paso 2: nodos clave = una comuna por nodo ("reciben" informacion).
-- Cada comuna se asigna al vertice de la red mas cercano a su punto interior, entre los
-- vertices que caen DENTRO de la comuna. Una comuna sin vertices no es nodo clave de ese escenario.
-- Escenario A: solo vertices de aristas de fibra.  Escenario B: cualquier vertice de la red.
DROP TABLE IF EXISTS nodos_clave;
CREATE TABLE nodos_clave AS
WITH v_tipo AS (
  SELECT source AS v, tipo FROM red_edges
  UNION ALL SELECT target, tipo FROM red_edges
),
esc AS (
  SELECT 'A'::text AS escenario, v FROM v_tipo WHERE tipo = 'fibra' GROUP BY v
  UNION ALL
  SELECT 'B', v FROM v_tipo GROUP BY v
)
SELECT DISTINCT ON (e.escenario, c.cod_comuna)
       e.escenario, c.cod_comuna, c.comuna, vv.id AS vertice,
       ST_Distance(vv.the_geom::geography, ST_PointOnSurface(c.geom)::geography) AS dist_m,
       vv.the_geom
FROM comunas c
JOIN red_edges_vertices_pgr vv ON ST_Within(vv.the_geom, c.geom)
JOIN esc e ON e.v = vv.id
ORDER BY e.escenario, c.cod_comuna, vv.the_geom <-> ST_PointOnSurface(c.geom);


-- =====================================================================
-- 05_probabilidades.sql  (pasos 6, 7 y 8)
-- Probabilidad de falla de cada enlace de red_edges ante el terremoto
-- Mw 8.8 del Maule (USGS official20100227063411530_30), cargado en la tabla sismo.
--
-- MODELO DE FALLA (respaldado en literatura sismica y de redes vitales):
--   1) Atenuacion GMPE para subduccion interplaca en suelo (Youngs et al., 1997,
--      SRL 68(1), Z_T = 0):
--        ln(PGA) = -0.6687 + 1.438*Mw - 2.329*ln(d + 1.097*exp(0.617*Mw)) + 0.00648*H
--      donde PGA esta en g, d es la distancia hipocentral en km y H = prof_km.
--   2) Conversion PGA -> PGV en suelo (Newmark & Hall, 1982 / HAZUS-MH):
--        PGV [cm/s] = 100 * PGA [g]
--   3) Curva de fragilidad para redes lineales (ALA, 2001):
--        RR(d) = K1 * 0.00187 * PGV(d)   [fallas por km]
--      donde K1 es el factor de material/ductilidad:
--        bajo: K1 = 0.3 (ductos ductiles HDPE/protegidos)
--        medio: K1 = 0.5 (referencia ductos ductiles/fibra troncal)
--        alto: K1 = 1.0 (tendido estandar/mayor vulnerabilidad)
--   4) Probabilidad de falla del enlace (proceso de Poisson por tramos <= 5 km):
--        P(enlace) = 1 - exp( - SUM_i RR(d_i) * largo_i )
--
-- Requiere PostGIS >= 3.2 (ST_DumpSegments).
-- =====================================================================

-- 1) Parametros de los escenarios (factor K1 de ALA, 2001)
DROP TABLE IF EXISTS params_falla;
CREATE TABLE params_falla (
  escenario text PRIMARY KEY,
  k1        double precision    -- factor de vulnerabilidad/material (ALA, 2001)
);

-- 2) Columnas de resultado
ALTER TABLE red_edges ADD COLUMN IF NOT EXISTS prob_bajo  double precision;
ALTER TABLE red_edges ADD COLUMN IF NOT EXISTS prob_medio double precision;
ALTER TABLE red_edges ADD COLUMN IF NOT EXISTS prob_alto  double precision;

-- 3) Calculo (Youngs et al. 1997 -> Newmark & Hall 1982 -> ALA 2001)
WITH s AS (
  SELECT geom::geography AS epi, mag, prof_km FROM sismo LIMIT 1
),
segs AS (
  SELECT e.id,
         (ST_DumpSegments(ST_Segmentize(e.geom::geography, 5000)::geometry)).geom AS seg
  FROM red_edges e
),
medidas AS (
  SELECT g.id,
         ST_Length(g.seg::geography) / 1000.0 AS len_km,
         SQRT( POWER(ST_Distance(ST_LineInterpolatePoint(g.seg, 0.5)::geography, s.epi) / 1000.0, 2)
             + POWER(s.prof_km, 2) ) AS d_km,
         s.mag,
         s.prof_km
  FROM segs g CROSS JOIN s
),
movimiento AS (
  SELECT m.id,
         m.len_km,
         100.0 * EXP(
           -0.6687
           + 1.438 * m.mag
           - 2.329 * LN(m.d_km + 1.097 * EXP(0.617 * m.mag))
           + 0.00648 * m.prof_km
         ) AS pgv_cms
  FROM medidas m
),
tasas AS (
  SELECT mv.id, p.escenario,
         SUM(p.k1 * 0.00187 * mv.pgv_cms * mv.len_km) AS rr_total
  FROM movimiento mv CROSS JOIN params_falla p
  GROUP BY mv.id, p.escenario
),
piv AS (
  SELECT id,
         1 - EXP(-MAX(rr_total) FILTER (WHERE escenario = 'bajo'))  AS p_bajo,
         1 - EXP(-MAX(rr_total) FILTER (WHERE escenario = 'medio')) AS p_medio,
         1 - EXP(-MAX(rr_total) FILTER (WHERE escenario = 'alto'))  AS p_alto
  FROM tasas
  GROUP BY id
)
UPDATE red_edges e
SET prob_bajo = piv.p_bajo,
    prob_medio = piv.p_medio,
    prob_alto = piv.p_alto,
    prob_falla = piv.p_medio
FROM piv
WHERE e.id = piv.id;

-- 4) Verificacion: resumen por tipo (escenario medio)
SELECT tipo,
       count(*)                                                 AS enlaces,
       round(avg(prob_medio)::numeric, 4)                       AS p_media,
       round(max(prob_medio)::numeric, 3)                       AS p_max,
       round((sum(prob_medio * length_m) / 1000)::numeric)      AS km_esperados_fallados,
       round((sum(length_m) / 1000)::numeric)                   AS km_total
FROM red_edges
GROUP BY tipo
ORDER BY tipo;

-- 5) Los 10 enlaces mas vulnerables (escenario medio)
SELECT id, tipo, es_sintetico, round(length_m::numeric) AS largo_m, round(prob_medio::numeric, 4) AS p_medio
FROM red_edges
ORDER BY prob_medio DESC
LIMIT 10;

-- 6) Los 10 enlaces menos vulnerables (escenario medio)
SELECT id, tipo, es_sintetico, round(length_m::numeric) AS largo_m, round(prob_medio::numeric, 6) AS p_medio
FROM red_edges
ORDER BY prob_medio ASC
LIMIT 10;
